  border-collapse: collapse;
  margin: 0 auto;
  margin-bottom: 18px;
}

.transaction-list th,
.transaction-list td {
  padding: 9px 8px;
  text-align: left;
}

.transaction-list th {
  color: var(--primary, #6C2EBE);
  border-bottom: 1.5px solid var(--border-color, #eaeafb);
  font-weight: 600;
}

.transaction-list tr {
  background: var(--surface, #fff);
  border-radius: 6px;
  transition: background 0.14s;
}

.transaction-list tr:hover {
  background: rgba(154, 143, 239, 0.06);
}

.amount-income {
  color: var(--income, #22C55E);
  font-weight: 600;
}
.amount-expense {
  color: var(--expense, #E74C3C);
  font-weight: 600;
}

.btn-edit {
  color: var(--primary, #6C2EBE);
  background: none;
  border: none;
  cursor: pointer;
  margin-right: 3px;
  font-size: 1em;
}
.btn-delete {
  color: var(--expense, #E74C3C);
  background: none;
  border: none;
  cursor: pointer;
  font-size: 1em;
}

@media (max-width: 500px) {
  .transaction-list th,
  .transaction-list td {
    padding: 7px 4px;
    font-size: 0.98em;
  }
}
